                            <Typography color="text.secondary" sx={{ minWidth: 0, overflowWrap: 'anywhere' }} variant="caption">
                                {taskText(task)}
                            </Typography>
                        </Stack>
                    ))}
                </Stack>
            </AccordionDetails>
        </Accordion>
    )
}

